import type { Vec3 } from '../../contracts/math';
import type { PlayerId } from '../../contracts/game';
import type { ZoneTriggerEvent, IZone } from '../../contracts/zones';

export class ZoneManager {
  private zones: Map<string, IZone> = new Map();

  addZone(zone: IZone): void {
    this.zones.set(zone.id, zone);
  }

  removeZone(zoneId: string): void {
    this.zones.delete(zoneId);
  }

  getZonesForPosition(position: Vec3): IZone[] {
    const active: IZone[] = [];
    for (const zone of this.zones.values()) {
      if (zone.contains(position)) {
        active.push(zone);
      }
    }
    return active;
  }

  checkTriggers(playerId: PlayerId, position: Vec3): ZoneTriggerEvent[] {
    const events: ZoneTriggerEvent[] = [];
    for (const zone of this.getZonesForPosition(position)) {
      const event = zone.onTrigger?.(playerId, position);
      if (event) {
        events.push(event);
      }
    }
    return events;
  }

  calculateForces(position: Vec3, velocity: Vec3, mass: number): Vec3 {
    let totalForce: Vec3 = { x: 0, y: 0, z: 0 };
    for (const zone of this.getZonesForPosition(position)) {
      const force = zone.getForce?.(position, velocity, mass);
      if (force) {
        totalForce.x += force.x;
        totalForce.y += force.y;
        totalForce.z += force.z;
      }
    }
    return totalForce;
  }
}
