import { describe, it, expect } from 'vitest';
import { WaterZone, LavaZone, KillZone, GravityZone, MagnetZone, ZoneManager } from './index';
import type { Vec3 } from '../../contracts/math';

describe('Zones', () => {
  const bounds = { min: { x: 0, y: 0, z: 0 }, max: { x: 10, y: 10, z: 10 } };
  const center: Vec3 = { x: 5, y: 5, z: 5 };
  const inside: Vec3 = { x: 5, y: 5, z: 5 };
  const outside: Vec3 = { x: 15, y: 15, z: 15 };

  describe('WaterZone', () => {
    it('should trigger and apply penalty', () => {
      const zone = new WaterZone('w1', bounds, 1);
      expect(zone.contains(inside)).toBe(true);
      expect(zone.contains(outside)).toBe(false);
      const resolution = zone.resolveHazard({ x: 0, y: 0, z: 0 });
      expect(resolution.penaltyStrokes).toBe(1);
    });
  });

  describe('LavaZone', () => {
    it('should have higher penalty', () => {
      const zone = new LavaZone('l1', bounds, 2);
      const resolution = zone.resolveHazard({ x: 0, y: 0, z: 0 });
      expect(resolution.penaltyStrokes).toBe(2);
    });
  });

  describe('KillZone', () => {
    it('should reset to safe position with penalty', () => {
      const zone = new KillZone('k1', bounds, 1, { x: 1, y: 1, z: 1 });
      const resolution = zone.resolveHazard({ x: 9, y: 9, z: 9 });
      expect(resolution.resetPosition).toEqual({ x: 1, y: 1, z: 1 });
      expect(resolution.penaltyStrokes).toBe(1);
    });
  });

  describe('GravityZone', () => {
    it('should apply downward force', () => {
      const zone = new GravityZone('g1', bounds, 9.81, { x: 0, y: -1, z: 0 });
      const force = zone.getForce!(center, { x: 0, y: 0, z: 0 }, 1);
      expect(force.y).toBeCloseTo(-9.81);
      expect(force.x).toBe(0);
    });
  });

  describe('MagnetZone', () => {
    it('should attract to center', () => {
      const zone = new MagnetZone('m1', bounds, 10, false);
      const pos: Vec3 = { x: 0, y: 5, z: 5 };
      const force = zone.getForce!(pos, { x: 0, y: 0, z: 0 }, 1);
      expect(force.x).toBeGreaterThan(0);
    });

    it('should repel from center', () => {
      const zone = new MagnetZone('m2', bounds, 10, true);
      const pos: Vec3 = { x: 0, y: 5, z: 5 };
      const force = zone.getForce!(pos, { x: 0, y: 0, z: 0 }, 1);
      expect(force.x).toBeLessThan(0);
    });
  });

  describe('ZoneManager', () => {
    it('should aggregate forces and triggers', () => {
      const manager = new ZoneManager();
      manager.addZone(new GravityZone('g1', bounds, 5, { x: 0, y: -1, z: 0 }));
      manager.addZone(new MagnetZone('m1', bounds, 2, false));

      const forces = manager.calculateForces(center, { x: 0, y: 0, z: 0 }, 1);
      expect(forces.y).toBeLessThan(0);

      const triggers = manager.checkTriggers('p1', center);
      expect(triggers.length).toBe(2);
    });
  });
});
